import Foundation
@testable import ReachyKit
import Testing

/// TEMPORARY probe — deleted before anything is committed. Reads a real
/// `list-available` answer off disk and puts it through the store.
@Suite("scratch: real catalogue through the store", .timeLimit(.minutes(5)))
struct ScratchCatalogueSizeTests {
    @Test("a real robot's catalogue survives a write and a read")
    func realCatalogue() async throws {
        let path = try #require(ProcessInfo.processInfo.environment["REACHY_CATALOGUE_JSON"])
        let raw = try Data(contentsOf: URL(fileURLWithPath: path))
        print("raw list-available: \(raw.count) bytes")

        var clock = ContinuousClock.now
        let infos = try JSONDecoder().decode([Components.Schemas.AppInfo].self, from: raw)
        print("decoded \(infos.count) AppInfo in \(ContinuousClock.now - clock)")

        let apps = infos.map(RobotApp.init)
        let record = RobotAppCatalogueRecord(robotID: "hw-probe", apps: apps)
        clock = .now
        let encoded = try JSONEncoder().encode(record)
        print("encoded record: \(encoded.count) bytes in \(ContinuousClock.now - clock)")
        print("maxRecordBytes: \(RobotCatalogueCache.maxRecordBytes) bytes")

        let root = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("scratch-catalogue-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let cache = RobotCatalogueCache(root: root)
        await cache.write(record)

        let stored = (try? Data(contentsOf: cache.url(.apps, for: "hw-probe")).count) ?? -1
        print("on disk after write: \(stored) bytes")

        clock = .now
        let back = await cache.record(RobotAppCatalogueRecord.self, for: "hw-probe")
        print("read back in \(ContinuousClock.now - clock): \(back?.apps.count.description ?? "nil")")

        #expect(back?.apps.count == apps.count)
    }
}

