import Foundation
@testable import ReachyKit
import Testing
import YYJSON

/// TEMPORARY spike — deleted before anything is committed. Foundation against
/// yyjson on this app's own payloads, in this app's own types.
///
/// Debug numbers, and the bias runs *against* yyjson: Foundation's decoder is a
/// prebuilt optimised system library, while yyjson's C core and its Swift glue are
/// compiled `-O0` here. A win measured in Debug is therefore a floor.
@Suite("scratch: yyjson vs Foundation", .timeLimit(.minutes(5)))
struct ScratchYYJSONSpikeTests {
    private func best(_ rounds: Int = 3, _ body: () throws -> Void) rethrows -> Duration {
        var best = Duration.seconds(3600)
        for _ in 0 ..< rounds {
            let start = ContinuousClock.now
            try body()
            best = min(best, ContinuousClock.now - start)
        }
        return best
    }

    private func ms(_ duration: Duration) -> String {
        let value = Double(duration.components.seconds) * 1000
            + Double(duration.components.attoseconds) / 1e15
        return String(format: "%.1f ms", value)
    }

    @Test("the real catalogue, both decoders")
    func catalogue() throws {
        let path = try #require(ProcessInfo.processInfo.environment["REACHY_CATALOGUE_JSON"])
        let raw = try Data(contentsOf: URL(fileURLWithPath: path))
        print("payload: \(raw.count) bytes")

        var foundationApps: [Components.Schemas.AppInfo] = []
        let foundationDecode = try best {
            foundationApps = try JSONDecoder().decode([Components.Schemas.AppInfo].self, from: raw)
        }
        var yyApps: [Components.Schemas.AppInfo] = []
        let yyDecode = try best {
            yyApps = try YYJSONDecoder().decode([Components.Schemas.AppInfo].self, from: raw)
        }
        print("DECODE  [AppInfo] x\(foundationApps.count)  Foundation \(ms(foundationDecode))  yyjson \(ms(yyDecode))")

        // Same objects, not merely the same count: a faster decoder that loses
        // `extra` would be the RobotAppSummary mistake with better timings.
        #expect(foundationApps.count == yyApps.count)
        #expect(foundationApps.map(RobotApp.init) == yyApps.map(RobotApp.init))

        let record = RobotAppCatalogueRecord(robotID: "hw-probe", apps: foundationApps.map(RobotApp.init))
        var foundationBytes = 0
        let foundationEncode = try best {
            foundationBytes = try JSONEncoder().encode(record).count
        }
        var yyBytes = 0
        let yyEncode = try best {
            yyBytes = try YYJSONEncoder().encode(record).count
        }
        print("ENCODE  record  Foundation \(ms(foundationEncode)) (\(foundationBytes) B)  yyjson \(ms(yyEncode)) (\(yyBytes) B)")

        // The warm path exactly: the record as it sits on disk, read back.
        let stored = try JSONEncoder().encode(record)
        let foundationWarm = try best {
            _ = try JSONDecoder().decode(RobotAppCatalogueRecord.self, from: stored)
        }
        let yyWarm = try best {
            _ = try YYJSONDecoder().decode(RobotAppCatalogueRecord.self, from: stored)
        }
        print("WARM    record  Foundation \(ms(foundationWarm))  yyjson \(ms(yyWarm))")

        let roundTripped = try YYJSONDecoder().decode(RobotAppCatalogueRecord.self, from: stored)
        #expect(roundTripped == record)
