/// The other shape that matters: a small frame, ten times a second, for as long
/// as a session lasts. Per-call overhead rather than throughput — and it carries
/// `JSONDecoder.reachyDaemon`'s custom date strategy, so this is also where the
/// existing rules are proved to port.
@Test("a state frame, both decoders, with the daemon's date rules")
func stateFrame() throws {
    let url = try #require(Bundle.module.url(
        forResource: "full_state",
        withExtension: "json",
        subdirectory: "Fixtures"
    ))
    let raw = try Data(contentsOf: url)
    print("state frame: \(raw.count) bytes")

    var yyjson = YYJSONDecoder()
    yyjson.dateDecodingStrategy = .custom { decoder in
        let container = try decoder.singleValueContainer()
        let string = try container.decode(String.self)
        let fractional = Date.ISO8601FormatStyle(includingFractionalSeconds: true)
        if let date = (try? Date(string, strategy: fractional)) ?? (try? Date(string, strategy: .iso8601)) {
            return date
        }
        throw DecodingError.dataCorruptedError(in: container, debugDescription: "Unrecognized ISO 8601")
    }

    let rounds = 1000
    let foundation = try best {
        for _ in 0 ..< rounds {
            _ = try JSONDecoder.reachyDaemon.decode(Components.Schemas.FullState.self, from: raw)
        }
    }
    let yy = try best {
        for _ in 0 ..< rounds {
            _ = try yyjson.decode(Components.Schemas.FullState.self, from: raw)
        }
    }
    print("DECODE  FullState x\(rounds)  Foundation \(ms(foundation))  yyjson \(ms(yy))")

    let a = try JSONDecoder.reachyDaemon.decode(Components.Schemas.FullState.self, from: raw)
    let b = try yyjson.decode(Components.Schemas.FullState.self, from: raw)
